import { AdminProductService } from './../../../../../../libs/openapi/src/api/admin-product.service';
import { Component, OnInit } from '@angular/core';
import { ConfirmationService, MessageService } from 'primeng/api';
import { Product } from '../../../../../../libs/openapi/src';
import { ToastModule } from 'primeng/toast';

@Component({
  selector: 'app-product-list',
  templateUrl: './product-list.component.html',
  styleUrls: ['./product-list.component.scss'],
  providers: [ConfirmationService, MessageService, ToastModule],
})
export class ProductListComponent implements OnInit {
  products: any[] = [];
  loading: boolean = true;
  selectedProduct: Product | null = null;

  categoryFormatter = (category: any[]) => {
    if (!category || !Array.isArray(category)) {
      return '';
    }
    return category.map((v) => v.name).join(', ');
  };

  constructor(
    private adminProductService: AdminProductService,
    private confirmationService: ConfirmationService,
    private messageService: MessageService
  ) {}

  ngOnInit() {
    this.loadProducts();
  }

  loadProducts() {
    this.loading = true;
    this.adminProductService.apiAdminProductGet().subscribe({
      next: (data) => {
        data.data.forEach((item: any) => {
          const f =
            item.images.find((img: any) => img.isMain) || item.images[0];
          item.imageUrl = f ? f.url : null;
        });
        this.products = data.data;
        this.loading = false;
      },
      error: () => {
        this.messageService.add({
          severity: 'error',
          summary: 'Error',
          detail: 'Failed to load products',
        });
        this.loading = false;
      },
    });
  }

  confirmDelete(product: Product) {
    this.confirmationService.confirm({
      message: `要刪除 ${product.name} 嗎?`,
      header: '確認刪除',
      icon: 'pi pi-exclamation-triangle',
      accept: () => {
        this.deleteProduct(product);
      },
    });
  }

  private deleteProduct(product: Product) {
    if (product._id) {
      this.adminProductService.apiAdminProductIdDelete(product._id).subscribe({
        next: (data) => {
          this.messageService.add({
            severity: 'success',
            summary: '成功',
            detail: `商品 ${data.data.name} 已刪除`,
          });
          this.loadProducts();
        },
        error: () => {
          this.messageService.add({
            severity: 'error',
            summary: '錯誤',
            detail: '伺服器錯誤',
          });
        },
      });
    }
  }
}
