import { CategoryService } from './../../../../../../libs/openapi/src/api/category.service';
import { Component, OnInit } from '@angular/core';
import {
  FormArray,
  FormBuilder,
  FormControl,
  FormGroup,
  Validators,
} from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { MessageService, PrimeNGConfig } from 'primeng/api';
import { FileUploadEvent } from 'primeng/fileupload';
import { PostImageUploadResponseModel } from '../../../../../../libs/openapi/src/model/post-image-upload-response-model';
import {
  AdminProductService,
  Category,
  GetProductResponseModelDataImagesInner,
  GetProductResponseModelDataProductOptionsInner,
} from '../../../../../../libs/openapi/src';
import { uniqueOptionsValidator } from '../../../../shared/validator/unique-options.validator';
import { filter, pairwise, startWith } from 'rxjs';

@Component({
  selector: 'app-product-form',
  templateUrl: './product-form.component.html',
  styleUrls: ['./product-form.component.scss'],
  providers: [MessageService],
})
export class ProductFormComponent implements OnInit {
  productForm: FormGroup;
  isEditMode = false;
  productId: number | null = null;
  loading = false;

  categories: Category[] = [];

  get productOptions(): FormArray<any> {
    return this.productForm.get('productOptions') as FormArray;
  }
  get productOptionsGroup() {
    return this.productOptions.controls as FormGroup[];
  }
  get productVariants(): FormArray<any> {
    return this.productForm.get('productVariants') as FormArray;
  }
  get productVariantsGroup() {
    return this.productVariants.controls as FormGroup[];
  }
  get useProductVariant(): FormControl {
    return this.productForm.get('useProductVariant') as FormControl;
  }

  fgGetPrice(fg: FormGroup) {
    return fg.get('price') as FormControl;
  }
  fgGetstock(fg: FormGroup) {
    return fg.get('stock') as FormControl;
  }
  fgGetOption(fg: FormGroup) {
    return fg.get('option') as FormControl;
  }

  /** 選取的上傳檔案 */
  files: any = [];
  totalSize: number = 0;
  totalSizePercent: number = 0;
  /** 上傳完畢檔案 */
  uploadedFiles: GetProductResponseModelDataImagesInner[] = [];

  constructor(
    private fb: FormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private adminProductService: AdminProductService,
    private messageService: MessageService,
    private config: PrimeNGConfig,
    private categoryService: CategoryService
  ) {
    this.productForm = this.fb.group({
      name: ['', [Validators.required, Validators.minLength(3)]],
      description: [''],
      summary: [''],
      price: [null, [Validators.min(0), Validators.required]],
      stock: [null, [Validators.min(0), Validators.required]],
      images: [[]],
      categories: [[]],
      productOptions: this.fb.array([]),
      productVariants: this.fb.array([]),
      useProductVariant: [false],
      isPublished: [false],
    });
  }

  ngOnInit() {
    // 取得分類
    this.categoryService.apiAdminCategoryGet().subscribe({
      next: (categories) => {
        this.categories = categories.data;
      },
      error: (error) => {
        this.messageService.add({
          severity: 'error',
          summary: 'Error',
          detail: 'Failed to load categories',
        });
      },
    });

    this.productId = this.route.snapshot.params['id'];
    if (this.productId) {
      this.isEditMode = true;
      this.loadData(this.productId);
    } else {
      this.togglePriceAndStockValidators(false);
      this.listenFormValueChanges();
    }
  }

  listenFormValueChanges() {
    this.productForm
      .get('productOptions')
      ?.valueChanges.pipe(
        // 以 null 作為初始值
        startWith(this.productOptions.value),
        // 將當前值與前一個值組合成一個數組
        pairwise(),
        // 過濾掉初始化的情況
        filter(([prev, curr]) => prev !== null),
        // 只有當結構發生變化時才繼續執行
        filter(([prev, curr]) => this.hasStructuralChanges(prev, curr))
      )
      .subscribe(([prev, curr]) => {
        this.updateProductVariants();
      });

    this.productForm
      .get('useProductVariant')
      ?.valueChanges.subscribe((show) => {
        this.togglePriceAndStockValidators(show);
      });
  }

  togglePriceAndStockValidators(show: boolean) {
    if (!show) {
      this.productForm.get('price')?.enable();
      this.productForm.get('stock')?.enable();
      this.productForm.get('productOptions')?.disable();
      this.productForm.get('productVariants')?.disable();
    } else {
      this.productForm.get('price')?.disable();
      this.productForm.get('stock')?.disable();
      this.productForm.get('productOptions')?.enable();
      this.productForm.get('productVariants')?.enable();
      if (this.productOptions.length === 0) {
        this.addProductOptionFC();
      }
    }
    this.productForm.get('price')?.updateValueAndValidity();
    this.productForm.get('stock')?.updateValueAndValidity();
  }

  loadData(id: number) {
    this.loading = true;

    this.adminProductService.apiAdminProductIdGet(`${id}`).subscribe({
      next: (product) => {
        this.productForm.patchValue({
          ...product.data,
          categories: product.data.categories.map((category) => category._id),
        });

        this.initializeProductOptions(product.data.productOptions);
        this.updateProductVariants();
        this.togglePriceAndStockValidators(
          product.data.useProductVariant || false
        );
        this.productVariants.patchValue(product.data.productVariants);
        this.uploadedFiles = product.data.images;
        this.loading = false;
        this.listenFormValueChanges();
      },
      error: (error) => {
        this.messageService.add({
          severity: 'error',
          summary: 'Error',
          detail: 'Failed to load product',
        });
        this.loading = false;
      },
    });
  }
  /**
   * 比較 productOptions 結構是否有變化
   */
  private hasStructuralChanges(prev: any[], curr: any[]): boolean {
    if (!prev || !curr) {
      return true;
    }

    // 檢查選項組數量是否變化
    if (prev.length !== curr.length) {
      return true;
    }

    // 檢查每個選項組中選項數量是否變化
    for (let i = 0; i < prev.length; i++) {
      if (!prev[i] || !curr[i]) {
        return true;
      }
      if (prev[i].options.length !== curr[i].options.length) {
        return true;
      }
    }
    return false;
  }

  initializeProductOptions(
    v: GetProductResponseModelDataProductOptionsInner[]
  ) {
    v.forEach(
      (productOption: GetProductResponseModelDataProductOptionsInner) => {
        this.addProductOptionFC(productOption);
      }
    );
  }

  addProductOptionFC(
    productOption?: GetProductResponseModelDataProductOptionsInner
  ) {
    if (!productOption) {
      productOption = {
        _id: '',
        name: '',
        options: [{ _id: '', value: '' }],
      };
    }
    const optionGroup = this.fb.group({
      _id: productOption?._id,
      name: [productOption?.name, Validators.required],
      options: this.fb.array(
        productOption.options.map((option) =>
          this.fb.group({
            _id: [option._id],
            value: [option.value, Validators.required],
          })
        ),
        uniqueOptionsValidator()
      ),
    });
    this.productOptions.push(optionGroup, { emitEvent: false }); // 填寫規格選項時再 emit
  }

  removeProductOption(index: number) {
    this.productOptions.removeAt(index);
  }

  initializeProductVariants() {}

  /** 檢查productOptions每個option都有值、無重複項目 */
  canUpdateProductVariants() {
    // 檢查productOptions每個option都有值
    const productOptions = this.productOptions.controls;
    for (let i = 0; i < productOptions.length; i++) {
      const options = productOptions[i].get('options') as FormArray;
      if (options.length === 0) {
        return false; // 如果有任何一個option沒有值，則返回false
      }
      for (let j = 0; j < options.length; j++) {
        if (!options.at(j).value) {
          return false; // 如果有任何一個option沒有值，則返回false
        }
      }
    }
    // 檢查productOptions無重複項目
    const uniqueOptions = new Set();
    for (let i = 0; i < productOptions.length; i++) {
      const options = productOptions[i].get('options') as FormArray;
      for (let j = 0; j < options.length; j++) {
        if (uniqueOptions.has(options.at(j).value)) {
          return false; // 如果有重複項目，則返回false
        }
        uniqueOptions.add(options.at(j).value);
      }
    }
    return true; // 如果所有檢查都通過，則返回true
  }

  /** 更新產品變體控制項 */
  updateProductVariants() {
    if (!this.canUpdateProductVariants()) {
      return;
    }
    const productOptions = this.productOptions.value;
    this.productVariants.clear();

    switch (productOptions.length) {
      case 1:
        productOptions[0].options.forEach((option: any, index: number) => {
          this.addProductVariantFC([index]);
        });
        break;

      case 2:
        productOptions[0].options.forEach((option: any, index: number) => {
          productOptions[1].options.forEach((option2: any, index2: number) => {
            this.addProductVariantFC([index, index2]);
          });
        });
        break;
    }
  }

  addProductVariantFC(tier_index: any) {
    const variantGroup = this.fb.group({
      _id: [null],
      tier_index: [tier_index],
      price: [null, [Validators.required, Validators.min(0)]],
      stock: [null, [Validators.required, Validators.min(0)]],
    });
    this.productVariants.push(variantGroup);
  }

  productVariantInfo(tier_index: any) {
    return tier_index.map((v: number, index: number) => {
      return this.productOptions.value[index].options[v].value;
    });
  }

  onSubmit() {
    if (this.productForm.valid) {
      this.loading = true;
      const productData = this.productForm.getRawValue();

      if (!productData.useProductVariant) {
        productData.productOptions = [];
        productData.productVariants = [];
      }

      // 確保圖片資料格式正確
      productData.images = this.uploadedFiles;

      const request =
        this.isEditMode && this.productId
          ? this.adminProductService.apiAdminProductIdPut(
              `${this.productId}`,
              '',
              productData
            )
          : this.adminProductService.apiAdminProductPost('', productData);

      request.subscribe({
        next: () => {
          this.messageService.add({
            severity: 'success',
            summary: 'Success',
            detail: `Product ${
              this.isEditMode ? 'updated' : 'created'
            } successfully`,
          });
          this.router.navigate(['/products']);
        },
        error: (error) => {
          if (error.error && error.error.message) {
            console.error('Backend error message:', error.error.message);
          }
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: `Failed to ${
              this.isEditMode ? 'update' : 'create'
            } product`,
          });
          this.loading = false;
        },
      });
    } else {
      // 檢查每個控制項的錯誤
      Object.keys(this.productForm.controls).forEach((key) => {
        const control = this.productForm.get(key);
        if (control && control.invalid) {
          console.log(`${key} is invalid:`, control.errors);
          console.log(`${key} value:`, control.value);
        }
      });

      // 檢查 FormArray 的錯誤
      if (this.productOptions.invalid) {
        console.log('ProductOptions errors:', this.productOptions.errors);
        this.productOptions.controls.forEach((control, index) => {
          if (control.invalid) {
            console.log(`ProductOption ${index} errors:`, control.errors);
          }
        });
      }

      if (this.productVariants.invalid) {
        console.log('ProductVariants errors:', this.productVariants.errors);
        this.productVariants.controls.forEach((control, index) => {
          if (control.invalid) {
            console.log(`ProductVariant ${index} errors:`, control.errors);
          }
        });
      }
    }
  }

  // productOptions

  getOptions(variantIndex: number): FormArray<FormGroup> {
    return this.productOptions.at(variantIndex).get('options') as FormArray;
  }

  addProductOptionOptionFC(variantIndex: number) {
    this.getOptions(variantIndex).push(
      this.fb.group({
        _id: [null],
        value: ['', Validators.required],
      }),
      { emitEvent: false }
    );
  }

  removeOption(variantIndex: number, optionIndex: number) {
    this.getOptions(variantIndex).removeAt(optionIndex);
  }

  // ./productOptions

  // 圖片相關

  formatSize(bytes: any) {
    const k = 1024;
    const dm = 3;
    const sizes = this.config.translation.fileSizeTypes!;
    if (bytes === 0) {
      return `0 ${sizes[0]}`;
    }

    const i = Math.floor(Math.log(bytes) / Math.log(k));
    const formattedSize = parseFloat((bytes / Math.pow(k, i)).toFixed(dm));

    return `${formattedSize} ${sizes[i]}`;
  }

  choose(event: any, callback: () => void) {
    callback();
  }

  onRemoveTemplatingFile(
    event: any,
    file: { size: any },
    removeFileCallback: (arg0: any, arg1: any) => void,
    index: any
  ) {
    removeFileCallback(event, index);
    this.totalSize -= parseInt(this.formatSize(file.size));
    this.totalSizePercent = this.totalSize / 10;
  }

  onClearTemplatingUpload(clear: () => void) {
    clear();
    this.totalSize = 0;
    this.totalSizePercent = 0;
  }

  onTemplatedUpload(event: FileUploadEvent) {
    const httpResponse = event.originalEvent as any;
    const oriRequest: PostImageUploadResponseModel =
      httpResponse.body as PostImageUploadResponseModel;
    oriRequest.data.forEach((file) => {
      this.uploadedFiles.push(file);
    });

    this.messageService.add({
      severity: 'info',
      summary: 'Success',
      detail: 'File Uploaded',
      life: 3000,
    });
  }

  onSelectedFiles(event: { currentFiles: any[] }) {
    this.files = event.currentFiles;
    this.files.forEach((file: any) => {
      this.totalSize += parseInt(this.formatSize(file.size));
    });
    this.totalSizePercent = this.totalSize / 10;
  }

  uploadEvent(callback: () => void) {
    callback();
  }

  removeUploadedFileCallback(i: number) {
    this.uploadedFiles.splice(i, 1);
  }
  // ./圖片相關
}
